'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pad=n=>String(n).padStart(2,'0');
const time=s=>Number.isFinite(s)?`${Math.floor(s/60)}:${String(Math.floor(s%60)).padStart(2,'0')}`:'0:00';
let book,current=0,visited=new Set(),marks=new Set(),settings={},audioReady=false,lastSave=0,codeAbort=null;
const audio=$('#audio');
function readStore(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
function writeStore(key,val){try{localStorage.setItem(key,JSON.stringify(val))}catch{}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3000)}
function download(url){const a=document.createElement('a');a.href=url;a.download=url.split('/').pop();document.body.append(a);a.click();a.remove()}
function modal(title,kicker,content){$('#modal-title').textContent=title;$('#modal-kicker').textContent=kicker;$('#modal-content').innerHTML=content;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0}
function closeMenu(){$('#sidebar').classList.remove('open');$('#menu-scrim').hidden=true;$('#toggle-menu').setAttribute('aria-expanded','false')}

const images={
 'observatory-map':['observatory-map.png','Actual browser simulator private-map telemetry in the 3D observatory. This is not a live ROS SLAM run.'],
 'observatory-network':['observatory-network.png','Actual browser transport links and packet events. A coordination layout, not GNN activations.'],
 'ppo-preview':['ppo-preview.png','Actual Python-generated setup preview: 40-cell maze, four rovers and two drones, before creating a mission.'],
 'ros-connection':['ros-connection.png','Current ROS interface while disconnected. No placeholder operational mapping evidence.'],
 'mission-control':['mission-control.png','Current running browser mission-control interface with compact controls and 3D world.'],
 'office':['office-overview.png','The actual React mission-control application: Office, seed 7, two rovers and two drones, before launch.'],
 'office-fleet':['office-fleet.png','Actual paused Office mission at step 12 with live fleet telemetry. Presentation capture, not a new benchmark.'],
 'mine':['mine-team.png','Actual Mine mission, seed 17, one rover and three drones. The discovery dialogue is authored fictional UI content.'],
 'apartment':['apartment-team.png','Actual Apartment mission, seed 23, three rovers and one drone, paused at step 10.'],
 'ppo-completed':['ppo-completed.png','Actual Python-backed PPO browser mission: development seed 10000, four of four found at step 94. One development reproduction.'],
 'gazebo':['03-gazebo-overview.png','Original supplied Gazebo host capture: one disaster world, one rover and two drones. See the gallery provenance note for the host policy mismatch.'],
 'gazebo-top':['07-gazebo-top.png','Another camera view of the same supplied Gazebo world/team. It is not a separate validated scenario.'],
 'rviz':['10-rviz-progress.png','Original RViz capture from the supplied host session. Occupancy mapping and reported detections; not a continuous video.'],
};
function figure(key){const [file,caption]=images[key];return `<figure class="figure"><span class="figure-tag">REAL PROJECT CAPTURE · CLICK TO EXPAND</span><img src="assets/${file}" alt="${escape(caption)}" loading="lazy" data-expand="assets/${file}" tabindex="0" role="button" aria-label="Expand ${escape(caption)}"><figcaption>${caption}</figcaption></figure>`}
function svg(content,w=360,h=195){return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Teaching diagram">${content}</svg>`}
function box(x,y,w,h,label,accent=false){return `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="3" fill="${accent?'#e6d6bd':'#e2e8d5'}" stroke="${accent?'#c28757':'#b6c4a3'}"/><text x="${x+w/2}" y="${y+h/2+4}" text-anchor="middle">${label}</text>`}
function line(x,y,x2,y2,dashed=false){return `<path d="M${x} ${y}L${x2} ${y2}" fill="none" stroke="#91a477" stroke-width="1.4" ${dashed?'stroke-dasharray="4 5"':''}/><circle cx="${x2}" cy="${y2}" r="2" fill="#b76d40"/>`}
function frame(title,body,caption='',controls=''){return `<section class="teaching"><div class="teaching-header">${title}<span>TEACHING ILLUSTRATION</span></div><div class="teaching-body">${body}${controls}${caption?`<p class="teaching-caption">${caption}</p>`:''}</div></section>`}
function coverDiagram(){let grid='';for(let i=0;i<11;i++)grid+=`<path d="M${i*36} 0V160M0 ${i*20}H360" stroke="#668156" stroke-opacity=".13"/>`;return `<svg class="cover-diagram" viewBox="0 0 360 160" aria-label="Illustrated robot team and shared search paths">${grid}<path d="M35 126L90 126L90 55L160 55L160 92L238 92L238 34L322 34" fill="none" stroke="#9db58a" stroke-opacity=".55" stroke-dasharray="3 6"/><path d="M84 123L160 55L242 93" stroke="#c68b5b" fill="none" stroke-opacity=".7"/><g transform="translate(83 123)"><rect x="-12" y="-8" width="24" height="16" rx="4" fill="#a6b58f"/><circle cx="-8" cy="10" r="4" fill="#5d7452"/><circle cx="8" cy="10" r="4" fill="#5d7452"/><circle r="3" fill="#243f2b"/></g>${[[160,55],[242,93]].map(([x,y])=>`<g transform="translate(${x} ${y})"><path d="M-11 -11L11 11M-11 11L11 -11" stroke="#d3d9bd" stroke-width="3"/>${[[-11,-11],[11,11],[-11,11],[11,-11]].map(([a,b])=>`<ellipse cx="${a}" cy="${b}" rx="8" ry="3" stroke="#819774" fill="#263f2f"/>`).join('')}<rect x="-5" y="-5" width="10" height="10" rx="3" fill="#b8bd98"/></g>`).join('')}<circle cx="322" cy="34" r="11" fill="none" stroke="#c98050"/><circle cx="322" cy="34" r="3" fill="#d29160"/><text x="13" y="17" fill="#77906a" font-size="7" font-family="monospace">32 × 32 / SEARCH SECTOR</text><text x="267" y="145" fill="#8fa27c" font-size="7" font-family="monospace">LOCAL → SHARED</text></svg>`}

function visual(type){
 if(!type)return '';
 if(images[type])return figure(type);
 if(type==='cover')return `<div class="cover-visual"><div class="visual-topline">FIELD OBSERVATION / 001<span>SWARM ONLINE ●</span></div>${coverDiagram()}<img src="assets/office-overview.png" alt="Real Swarm SAR Office mission-control screenshot" data-expand="assets/office-overview.png" tabindex="0" role="button" aria-label="Expand the real mission control screenshot"><p class="capture-note">ACTUAL MISSION CONTROL · OFFICE SCENARIO<br>2 ROVERS + 2 DRONES / BEFORE LAUNCH</p></div><p class="cover-note">Search together.<br>Share discoveries.<br><strong>Understand every decision.</strong></p><div class="cover-details"><span>FROM FIRST PRINCIPLES</span><span>TO THE ACTUAL CODE</span></div>`;
 if(type==='team')return `<div class="team-grid">${[['OR','Om Rashiya'],['YB','Yash Bharvada'],['PS','Purva Shah'],['PA','Pankti Akbari']].map(([i,n])=>`<div class="team-person"><span class="initials">${i}</span><strong>${n}</strong><span>PROJECT TEAM</span></div>`).join('')}</div>`;
 if(['fog','grid','frontier'].includes(type)){let cells='';const walls=new Set([4,14,24,34,35,36,46,56,66,65,64,21,22,71,72,73,18,28,38]);for(let y=0;y<8;y++)for(let x=0;x<10;x++){const i=y*10+x;cells+=`<rect class="grid-cell" data-x="${x}" data-y="${y}" data-wall="${walls.has(i)?1:0}" x="${31+x*29}" y="${14+y*24}" width="26" height="21" rx="1" fill="#cbd2bd" stroke="#bdc8ac"/>`}return frame('THE MAP IN YOUR NOTEBOOK',svg(cells+'<circle cx="72" cy="170" r="5" fill="#bd653f"/><text x="31" y="227" class="label">GRAY / UNKNOWN</text><text x="172" y="227" class="label">ORANGE / FRONTIER</text>',360,240),'This simplified map illustrates visibility and frontier boundaries. It does not run the project simulator.',`<div class="figure-controls"><label for="reveal">Knowledge radius</label><input id="reveal" type="range" min="1" max="11" value="3"></div>`)}
 if(type==='robots')return frame('DIFFERENT TOOLS, SHARED MISSION',svg(box(13,30,150,80,'ROVER',true)+box(197,30,150,80,'DRONE')+line(163,70,197,70,true)+'<text x="88" y="140" text-anchor="middle">4-cell vision</text><text x="88" y="160" text-anchor="middle">300 battery</text><text x="272" y="140" text-anchor="middle">7-cell vision</text><text x="272" y="160" text-anchor="middle">240 battery</text>'),'Grid-model configuration. Drone flight appearance does not change its 2D traversal rules.');
 if(['architecture','paths','bridge'].includes(type))return frame('FOLLOW THE OWNER OF THE STATE',svg(box(80,4,200,35,'REACT MISSION CONTROL')+line(130,39,75,77)+line(230,39,282,77)+box(5,77,145,44,'TS HEURISTIC')+box(205,77,150,44,'PYTHON PPO',true)+line(280,121,280,151)+box(205,151,150,35,'PYTHON GRID')+box(5,151,145,35,'ROS / GAZEBO')+line(75,121,75,151,true)+'<text x="180" y="214" text-anchor="middle" class="label">ROS IS A SEPARATE PHYSICS PATH</text>',360,225),'Solid lines show the browser runtime choices. ROS/Gazebo is a separate implementation path, connected by concepts and contracts.');
 if(type==='timeline')return frame('BUILT IN LAYERS',`<div>${[['01','World, sensing and environment'],['02','Frontier reference and topology'],['2.5','Scale and budget audits'],['03','Shared PPO policies'],['04','Peer transport and expert'],['05+','GPU learning and integration']].map(([n,t])=>`<div class="timeline-row"><span>${n}</span><strong>${t}</strong></div>`).join('')}</div>`);
 if(['learning-loop','step-loop'].includes(type))return frame('ONE DECISION AT A TIME',svg(box(10,15,130,42,'OBSERVATION')+box(220,15,130,42,'POLICY',true)+box(220,130,130,42,'ACTION')+box(10,130,130,42,'ENVIRONMENT')+line(140,36,220,36)+line(285,57,285,130)+line(220,151,140,151)+line(75,130,75,57)+'<text x="180" y="98" text-anchor="middle" class="label">REPEAT UNTIL MISSION ENDS</text>'),'Training adds rewards and updates weights. Demonstration inference uses the saved weights.');
 if(type==='astar')return frame('CHOOSING A PATH',svg('<path d="M40 155H100V85H250V35H320" fill="none" stroke="#a3b28c" stroke-width="19" stroke-linejoin="round"/><path d="M40 155H100V85H250V35H320" fill="none" stroke="#b57045" stroke-width="2" stroke-dasharray="4 5"/><circle cx="40" cy="155" r="8" fill="#314e32"/><circle cx="320" cy="35" r="8" fill="#be7045"/><text x="28" y="185">START</text><text x="285" y="16">FRONTIER</text><text x="145" y="143">f = g + h</text>'),'Illustrative A* route on known traversable space. The learned action chooses a candidate; the planner finds the next step.');
 if(type==='traffic')return frame('JOINT MOVEMENT, NOT A FOR-LOOP',svg(box(13,40,75,40,'A')+box(145,40,75,40,'B')+box(277,40,70,40,'FREE')+line(88,60,145,60)+line(220,60,277,60)+'<text x="180" y="120" text-anchor="middle">Safe convoy: both advance</text><path d="M78 153H285" stroke="#b87046" stroke-width="1.5" stroke-dasharray="4 5"/><text x="180" y="185" text-anchor="middle">Swap / duplicate target: blocked</text>'),'Movement is resolved simultaneously. The shield and resolver contribute to recorded collision outcomes.');
 if(type==='sensor')return frame('CLUES BECOME LESS CLEAR WITH DISTANCE',svg('<circle cx="180" cy="100" r="82" fill="none" stroke="#c0cbae"/><circle cx="180" cy="100" r="55" fill="none" stroke="#c0cbae"/><path d="M180 18V182M98 100H262" stroke="#c0cbae"/><path d="M180 100L230 40" stroke="#b97045" stroke-width="2"/><circle cx="180" cy="100" r="8" fill="#45613a"/><circle cx="230" cy="40" r="5" fill="#be7445"/><text x="284" y="48">HEAT</text><text x="284" y="66">+ NOISE</text><text x="14" y="186" class="label">DIRECTIONAL THERMAL / OMNI ACOUSTIC</text>'),'The grid models noisy scalar readings, not thermal images or a calibrated microphone array.');
 if(type==='topology')return frame('PLACES AND CONNECTIONS',svg(line(45,100,120,40)+line(120,40,220,60)+line(45,100,130,165)+line(130,165,220,60)+line(220,60,310,140)+[[45,100,'ENTRY'],[120,40,'FRONTIER'],[130,165,'JUNCTION'],[220,60,'CLUE'],[310,140,'FRONTIER']].map(([x,y,t])=>`<circle cx="${x}" cy="${y}" r="9" fill="${t==='CLUE'?'#c17b4a':'#829a69'}"/><text x="${x}" y="${y+26}" text-anchor="middle" class="label">${t}</text>`).join('')),'A hand-drawn teaching graph. The actual Python topology is constructed with NetworkX; it is not a graph neural network.');
 if(type==='network')return frame('MESSAGES MUST CROSS THE CHANNEL',svg(line(65,95,177,45,true)+line(177,45,295,95,true)+line(65,95,177,158,true)+line(177,158,295,95,true)+[[65,95,'ROVER'],[177,45,'DRONE'],[177,158,'ROVER'],[295,95,'DRONE']].map(([x,y,t])=>`<circle cx="${x}" cy="${y}" r="16" fill="#dfe7cf" stroke="#91a477"/><circle cx="${x}" cy="${y}" r="5" fill="#66834b"/><text x="${x}" y="${y+32}" text-anchor="middle" class="label">${t}</text>`).join('')+'<text id="packet-label" x="177" y="103" text-anchor="middle">70 / 100</text>'),'An expected-delivery illustration only. Real runs also include range, walls, delay, bandwidth, expiry and partitions.',`<div class="figure-controls"><label for="loss">Packet loss <span id="loss-value">30%</span></label><input id="loss" type="range" min="0" max="100" value="30"></div>`);
 if(type==='reward')return frame('THE GPU TEAM REWARD',`<div class="stat-grid"><div class="stat"><strong>+50</strong><span>PER NEW SURVIVOR</span></div><div class="stat"><strong>+.02</strong><span>PER NEW TEAM CELL</span></div></div><div class="figure-controls"><label for="new-cells">New cells <span id="cells-value">20</span></label><input id="new-cells" type="range" min="0" max="100" value="20"></div><div class="interactive-result" id="reward-result">No new survivor / no collision: 0.39</div>`,'This calculation illustrates one joint step with no survivor discovery or collision. It is not a training log.');
 if(type==='memory')return frame('SHARED SKILL, SEPARATE NOTEBOOKS',svg(box(90,8,180,45,'ROVER POLICY WEIGHTS',true)+line(125,53,70,95)+line(235,53,290,95)+box(0,95,140,45,'ROVER A STATE')+box(220,95,140,45,'ROVER B STATE')+'<text x="70" y="170" text-anchor="middle">Own observations</text><text x="290" y="170" text-anchor="middle">Own observations</text>'),'One trained module can serve multiple agents. Recurrent state belongs to an individual mission history.');
 if(type==='actor-critic')return frame('TWO LEARNING ROLES',svg(box(90,6,180,40,'LOCAL OBSERVATION')+line(130,46,80,94)+line(230,46,280,94)+box(5,94,150,45,'ACTOR',true)+box(205,94,150,45,'CRITIC')+'<text x="80" y="169" text-anchor="middle">Action probabilities</text><text x="280" y="169" text-anchor="middle">Expected return</text>'),'Both branches receive the encoded local view in this implementation. A shared team reward is not a centralized critic.');
 if(type==='ppo')return frame('POSITIVE ADVANTAGE / CLIPPED INCENTIVE',`<div class="figure-controls"><label for="ratio">Probability ratio <span id="ratio-value">1.50</span></label><input id="ratio" type="range" min="40" max="180" value="150"></div><div class="stat-grid"><div class="stat"><strong id="raw-objective">3.00</strong><span>UNCLIPPED × ADVANTAGE</span></div><div class="stat"><strong id="clip-objective">2.40</strong><span>CLIPPED CONTRIBUTION</span></div></div><div class="interactive-result">Advantage = +2 · clip parameter = 0.2</div>`,'Move the ratio. With positive advantage, the clipped objective stops rewarding a probability increase beyond the upper boundary. This is not a hard parameter-change limit.');
 if(type==='observation')return frame('THE INPUT CONTRACT',`<div class="stat-grid"><div class="stat"><strong>129</strong><span>HISTORICAL PREFIX</span></div><div class="stat"><strong>+100</strong><span>GPU-V1 EXTENSION</span></div></div><div class="interactive-result">229 float32 features<br>+ 7 separate action-mask values<br>→ 7 action logits</div>`,'Feature order, scale and meanings must match the saved model, not just the total length.');
 if(type==='training-pipeline')return frame('DEMONSTRATIONS → PRACTICE → REVIEW',svg(box(55,0,250,35,'DECENTRALIZED EXPERT')+line(180,35,180,53)+box(55,53,250,35,'RECURRENT BEHAVIOR CLONING')+line(180,88,180,106)+box(55,106,250,35,'ON-POLICY PPO PRACTICE',true)+line(180,141,180,159)+box(55,159,250,35,'COHORTS → GATES → HANDOFF')),'A candidate advances because of scoped quality checks, not simply because it is the latest checkpoint.');
 if(type==='results')return frame('PAIRED DEVELOPMENT COMPARISON',`<div class="result-bars">${[['Selected PPO',88.8],['Paired expert',87.13],['Random masked',28.52],['Frontier zero',22.27]].map(([n,v])=>`<div class="result-bar"><div><span>${n}</span><strong>${v.toFixed(2)}%</strong></div><div class="bar-track"><span style="width:${v}%"></span></div></div>`).join('')}</div>`,'Recorded combined mean cohort recall from the selected checkpoint review. Development selection evidence; final seeds were not used.');
 if(type==='cohorts')return frame('THE AVERAGE DOES NOT TELL THE WHOLE STORY',`<div class="stat-grid"><div class="stat"><strong>5 / 18</strong><span>LARGE-MAZE SURVIVORS</span></div><div class="stat"><strong>15 / 21</strong><span>TUNNEL SURVIVORS</span></div></div><div class="interactive-result">Large-maze mean coverage: 19.15%<br>Source: selected development review</div>`,'These recorded cohort outcomes identify a material weakness, even alongside the stronger combined mean.');
 if(type==='ros-flow')return frame('FROM A COMMAND TO A REPORTED MAP',svg(box(0,10,145,40,'ROS CONTROLLER')+box(215,10,145,40,'ROS_GZ BRIDGE')+line(145,30,215,30)+line(287,50,287,105)+box(215,105,145,40,'GAZEBO')+line(215,125,145,125)+box(0,105,145,40,'SCAN / ODOMETRY')+line(72,145,72,179)+box(0,179,145,35,'MAP → RVIZ')+'<text x="180" y="82" text-anchor="middle" class="label">COMMANDS OUT / SENSOR DATA BACK</text>',360,225),'Namespaces and typed messages keep robot streams distinct. Simulation clock and transforms help data agree in time and space.');
 if(type==='atlas')return frame('THE REPOSITORY AT A GLANCE',`<div class="atlas-tree">swarm/<br>├─ frontend/ <span>the control room</span><br>├─ backend/ <span>the PPO bridge</span><br>├─ simulation/ <span>world + ROS</span><br>├─ training/ <span>teaching + evaluation</span><br>├─ models/ <span>preserved weights</span><br>├─ configs/ <span>shared parameters</span><br>├─ tests/ <span>software checks</span><br>└─ docs/ <span>guides + evidence</span></div><button class="small-button" data-action="files">Explore all ${book.files.length} files →</button>`);
 if(type==='qa')return `<div>${book.questions.slice(0,4).map(([q,a])=>`<details class="practice-card"><summary>${escape(q)}</summary><p>${escape(a)}</p></details>`).join('')}<button class="primary-button" data-action="practice">Practice all 12 questions →</button></div>`;
 if(type==='closing')return figure('ppo-completed')+`<div class="cover-note">From “what is PPO?”<br>to “let me show you<br><strong>how our project works.”</strong></div>`;
 return '';
}

function sourceLinks(page){return `<div class="source-block"><div class="source-label">FOLLOW IT INTO THE CODE <span>↗</span></div><div class="source-links">${page.sources.map(path=>`<button class="source-link" data-source="${escape(path)}" title="${escape(path)}">${escape(path.split('/').pop())}</button>`).join('')}</div></div>`}
function pageMarkup(page){const ch=book.chapters[page.chapter],num=pad(page.id+1);const cover=page.kind==='cover';return `<article class="paper-page left-page"><div class="running-head"><span>SWARM SAR / THE FIELDBOOK</span><span class="chapter-no">${cover?'VOL. 01':`CHAPTER ${pad(page.chapter)}`}</span></div>${cover?`<p class="cover-subtitle">A BEGINNER’S GUIDE TO OUR PROJECT</p><h1 class="cover-title">Small robots.<br>One big<br><em>mission.</em></h1><p class="cover-intro">From your first robot to reinforcement learning. An illustrated, narrated journey through the project we built.</p><div class="cover-cta"><button class="primary-button" data-action="begin">Open the book <span>↗</span></button><button class="secondary-button" data-action="listen">▶ Listen</button></div><div class="team-credit"><span>THE TEAM BEHIND THE SWARM</span><div class="team-names"><span>Om Rashiya</span><span>Yash Bharvada</span><span>Purva Shah</span><span>Pankti Akbari</span></div></div>`:`<h1 class="lesson-title">${page.title}</h1><p class="deck">${page.deck}</p><div class="prose">${page.body}</div>`}<div class="folio"><span>${cover?'PREFACE / START HERE':escape(ch.title.toUpperCase())}</span><span>${num}</span></div></article><aside class="paper-page right-page" aria-label="Illustrations and field notes"><div class="running-head"><span>${cover?'LOOK INSIDE THE MISSION':'ILLUSTRATIONS & FIELD NOTES'}</span><span>↗</span></div>${visual(page.visual)}${cover?'':`<div class="prose">${page.notes}</div>${sourceLinks(page)}`}<div class="folio"><span>${cover?'ENGLISH · ILLUSTRATED · SOURCE-LINKED':'READ. LISTEN. TRACE THE CODE.'}</span><span>${num} / NOTES</span></div></aside>`}
function savePosition(){writeStore('swarm-book-place',{page:current,time:audio.currentTime||0});writeStore('swarm-book-visited',[...visited])}
function navigate(index,{autoplay=false,animate=true,restoreTime=0}={}){
 if(!book)return;index=Math.max(0,Math.min(book.pages.length-1,index));const direction=index>=current?'next':'prev';const oldLeaf=$('#spread .'+(direction==='next'?'right-page':'left-page'))?.outerHTML;audio.pause();current=index;const page=book.pages[current],ch=book.chapters[page.chapter];visited.add(current);
 $('#spread').className='spread'+(page.kind==='cover'?' cover':'');$('#spread').innerHTML=pageMarkup(page);if(animate&&oldLeaf&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const leaf=document.createElement('div');leaf.className='turn-leaf turn-leaf-'+direction;leaf.setAttribute('aria-hidden','true');leaf.innerHTML='<div class="leaf-front">'+oldLeaf+'</div><div class="leaf-back"></div>';leaf.querySelectorAll('[id]').forEach(e=>e.removeAttribute('id'));$('#spread').append(leaf);setTimeout(()=>leaf.remove(),650)}
 $('#top-chapter').textContent=ch.title;$('#chapter-kicker').textContent=page.kind==='cover'?'A FIELD GUIDE TO COLLECTIVE INTELLIGENCE':`CHAPTER ${pad(page.chapter)} / ${ch.subtitle.toUpperCase()}`;$('#page-current').textContent=pad(current+1);$('#prev').disabled=current===0;$('#next').disabled=current===book.pages.length-1;$('#next').innerHTML=current===book.pages.length-1?'The end <span>✓</span>':'Next page <span>→</span>';
 $$('.chapter-link').forEach(el=>{const active=+el.dataset.chapter===page.chapter;el.classList.toggle('active',active);el.setAttribute('aria-current',active?'page':'false')});
 $('#read-percent').textContent=Math.round(visited.size/book.pages.length*100)+'%';$('#read-progress').style.width=visited.size/book.pages.length*100+'%';$('#track-title').textContent=page.title;$('#duration').textContent=time(page.duration||0);$('#elapsed').textContent='0:00';$('#seek').value=0;$('#bookmark-button').setAttribute('aria-pressed',String(marks.has(current)));$('#bookmark-button').setAttribute('aria-label',marks.has(current)?'Remove bookmark':'Bookmark this page');audio.src=page.audio;audio.playbackRate=settings.rate||1;audioReady=false;
 if(restoreTime>0)audio.addEventListener('loadedmetadata',()=>{audio.currentTime=Math.min(restoreTime,audio.duration||0)},{once:true});
 history.replaceState(null,'',`#page=${current+1}`);document.title=`${page.title} — SWARM SAR Fieldbook`;closeMenu();if(animate)window.scrollTo({top:0,behavior:'instant'});savePosition();initVisual();if(autoplay)playAudio();
}
function initVisual(){
 if($('#reveal')){const update=()=>{const radius=+$('#reveal').value;const known=(x,y)=>Math.hypot(x-1,y-6)<=radius;$$('.grid-cell').forEach(c=>{const x=+c.dataset.x,y=+c.dataset.y,w=c.dataset.wall==='1',seen=known(x,y),frontier=seen&&!w&&[[1,0],[-1,0],[0,1],[0,-1]].some(([dx,dy])=>x+dx>=0&&x+dx<10&&y+dy>=0&&y+dy<8&&!known(x+dx,y+dy));c.setAttribute('fill',!seen?'#cbd2bd':w?'#64785b':frontier?'#c08752':'#eff1e2')})};$('#reveal').addEventListener('input',update);update()}
 if($('#loss'))$('#loss').addEventListener('input',()=>{$('#loss-value').textContent=$('#loss').value+'%';$('#packet-label').textContent=(100-$('#loss').value)+' / 100'});
 if($('#new-cells'))$('#new-cells').addEventListener('input',()=>{$('#cells-value').textContent=$('#new-cells').value;$('#reward-result').textContent='No new survivor / no collision: '+(.02*$('#new-cells').value-.01).toFixed(2)});
 if($('#ratio'))$('#ratio').addEventListener('input',()=>{const r=$('#ratio').value/100;$('#ratio-value').textContent=r.toFixed(2);$('#raw-objective').textContent=(r*2).toFixed(2);$('#clip-objective').textContent=Math.min(r*2,Math.max(.8,Math.min(1.2,r))*2).toFixed(2)})
}
async function playAudio(){try{document.body.classList.add('audio-loading');await audio.play();document.body.classList.remove('audio-loading')}catch{document.body.classList.remove('audio-loading');toast('Playback could not start. Press play to try again.')}}
function toggleAudio(){audio.paused?playAudio():audio.pause()}
function updatePlaying(){const playing=!audio.paused;$('#play-icon').textContent=playing?'Ⅱ':'▶';$('#play').setAttribute('aria-label',playing?'Pause narration':'Play narration');if('mediaSession'in navigator)navigator.mediaSession.playbackState=playing?'playing':'paused'}
function openSearch(){modal('Find your next answer','SEARCH THE ENTIRE BOOK',`<input class="modal-input" id="search-input" placeholder="Try PPO, thermal, Gazebo, reward…" aria-label="Search book"><div class="file-count-note" id="search-count"></div><div class="search-results" id="search-results"></div>`);const update=()=>{const q=$('#search-input').value.trim().toLowerCase();let results=book.pages.filter(p=>!q||[p.title,p.deck,p.text,...p.sources].join(' ').toLowerCase().includes(q));$('#search-count').textContent=`${results.length} PAGES${q?' MATCH YOUR SEARCH':' · START ANYWHERE'}`;$('#search-results').innerHTML=results.length?results.map(p=>{let snippet=p.deck;if(q){const at=p.text.toLowerCase().indexOf(q);if(at>=0)snippet=(at>35?'…':'')+p.text.slice(Math.max(0,at-35),at+160).replace(/\n/g,' ')+'…'}return `<button class="result" data-page="${p.id}"><small>PAGE ${pad(p.id+1)} / ${escape(book.chapters[p.chapter].title)}</small><strong>${escape(p.title)}</strong><p>${escape(snippet)}</p></button>`}).join(''):'<div class="empty-state">No pages found. Try a broader word, such as “policy” or “map”.</div>'};$('#search-input').addEventListener('input',update);update();setTimeout(()=>$('#search-input').focus(),20)}
function openFiles(){let category='all';modal('The repository atlas','REVIEWED PROJECT FILES',`<p class="modal-note">${book.files.length} project files (generated fieldbook excluded) from source ${book.revision.slice(0,10)}. Open readable source with line numbers. Binary artifacts are catalogued with size and integrity metadata.</p><input class="modal-input" id="file-input" placeholder="Search paths, purposes or declarations…" aria-label="Search repository files"><div class="filter-row" id="file-filters">${['all','frontend','backend','simulation','training','models','configs','tests','docs','root'].map(c=>`<button class="chip ${c==='all'?'active':''}" data-category="${c}">${c}</button>`).join('')}</div><div class="file-count-note" id="file-matches"></div><div class="search-results" id="file-results"></div>`);const update=()=>{const q=$('#file-input').value.toLowerCase().trim(),files=book.files.filter(f=>(category==='all'||f.category===category)&&(!q||[f.path,f.purpose,...f.declarations.map(d=>d.name)].join(' ').toLowerCase().includes(q)));$('#file-matches').textContent=files.length+' FILES'+(q?' MATCH':'');$('#file-results').innerHTML=files.length?files.map(f=>`<button class="result" data-source="${escape(f.path)}"><small>${f.readable?'READ SOURCE':'BINARY ARTIFACT'} · ${f.size>1048576?(f.size/1048576).toFixed(1)+' MB':Math.max(1,Math.round(f.size/1024))+' KB'}${f.lines?' · '+f.lines+' LINES':''}</small><strong>${escape(f.path)}</strong><p>${escape(f.purpose)}</p></button>`).join(''):'<div class="empty-state">No matching files.</div>'};$('#file-input').addEventListener('input',update);$('#file-filters').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(!b)return;category=b.dataset.category;$$('#file-filters .chip').forEach(c=>c.classList.toggle('active',c===b));update()});update();setTimeout(()=>$('#file-input').focus(),20)}
async function openSource(path){if(codeAbort)codeAbort.abort();const f=book.files.find(f=>f.path===path);if(!f){toast('This file was not in the reviewed snapshot.');return}modal(path.split('/').pop(),'SOURCE / '+f.category.toUpperCase(),`<button class="small-button" data-action="files">← Back to all files</button><p class="modal-note" style="overflow-wrap:anywhere">${escape(path)}<br>${escape(f.purpose)}</p><div class="code-toolbar"><span>${f.size.toLocaleString()} bytes${f.lines?' · '+f.lines.toLocaleString()+' lines':''}</span>${f.url?`<a href="${f.url}" download>Download source</a>`:''}<button class="small-button" id="copy-path">Copy path</button></div><details><summary class="modal-note">Integrity / SHA-256</summary><p class="modal-note" style="overflow-wrap:anywhere;font-family:monospace">${f.sha256}</p></details><div id="source-content">${f.readable?'<p class="modal-note">Loading source…</p>':'<p class="modal-note">This binary artifact is preserved in the project repository. The reader catalogs it without embedding or executing model weights and datasets.</p>'}</div>`);$('#copy-path').onclick=()=>navigator.clipboard?.writeText(path).then(()=>toast('File path copied.')).catch(()=>toast(path));if(!f.readable)return;
 if(codeAbort)codeAbort.abort();codeAbort=new AbortController();try{const response=await fetch(f.url,{signal:codeAbort.signal});if(!response.ok)throw Error('HTTP '+response.status);const text=await response.text();if(!$('#source-content'))return;const lines=text.split('\n');let limit=400;function draw(){if(!$('#source-content'))return;$('#source-content').innerHTML=`<div class="declarations">${f.declarations.slice(0,30).map(d=>`<button data-line="${d.line}">${escape(d.name)} : ${d.line}</button>`).join('')}</div><div class="code-viewer" id="code-viewer">${lines.slice(0,limit).map((line,i)=>`<div class="code-line" id="line-${i+1}"><span class="line-num">${i+1}</span><span class="line-text">${escape(line)||' '}</span></div>`).join('')}</div>${lines.length>limit?`<button class="small-button" id="more-code" style="margin-top:12px">Load more (${Math.min(1000,lines.length-limit)} lines)</button>`:''}`;if($('#more-code'))$('#more-code').onclick=()=>{limit+=1000;draw()};$('.declarations').onclick=e=>{const b=e.target.closest('[data-line]');if(!b)return;const line=+b.dataset.line;if(line>limit){limit=line+100;draw()}$('#code-viewer').scrollTop=Math.max(0,(line-4)*20)}}draw()}catch(e){if(e.name!=='AbortError'&&$('#source-content'))$('#source-content').innerHTML='<p class="modal-note">Source could not load. Check the connection and reopen the file.</p>'}}
function openPractice(){modal('Explain it in your own words','HACKATHON / 12 PRACTICE QUESTIONS',`<p class="modal-note">Answer aloud before opening each card. Aim for the mechanism, the implementation and the evidence boundary.</p>${book.questions.map(([q,a],i)=>`<details class="practice-card"><summary>${pad(i+1)} · ${escape(q)}</summary><p>${escape(a)}</p></details>`).join('')}<button class="primary-button" data-page="${book.chapters[14].start}">Read the presentation chapter →</button>`)}
function openBookmarks(){const entries=[...marks].sort((a,b)=>a-b);modal('Your saved pages','BOOKMARKS / STORED ON THIS DEVICE',entries.length?entries.map(i=>`<button class="result" data-page="${i}"><small>PAGE ${pad(i+1)} · ${escape(book.chapters[book.pages[i].chapter].title)}</small><strong>${escape(book.pages[i].title)}</strong></button>`).join(''):'<div class="empty-state">Save a page with the bookmark button in the top bar. Your bookmarks will appear here.</div>')}
function openDownloads(){modal('Take the book with you','READ OFFLINE / LISTEN ANYWHERE',`<p class="modal-note">${book.pages.length} pages · ${book.chapters.length} chapters · ${book.wordCount.toLocaleString()} words · ${Math.round(book.audioDuration/60)} minutes of synthetic English narration. Narrator: Samantha, generated with macOS text-to-speech.</p><div class="download-card"><div><h3>The complete audiobook</h3><p>One M4B file with a chapter marker for every book page.<br>About 24 MB. Import into an audiobook player.</p></div><a class="primary-button" href="swarm-sar-fieldbook.m4b" download>Download audio ↓</a></div><div class="download-card"><div><h3>The illustrated book</h3><p>A printable PDF with the full manuscript and real project images.</p></div><a class="primary-button" href="swarm-sar-fieldbook.pdf" download>Download PDF ↓</a></div><div class="download-card"><div><h3>The full transcript</h3><p>Plain English text, technical examples and source references.</p></div><a class="secondary-button" href="swarm-sar-fieldbook.txt" download>Download text ↓</a></div><div class="download-card"><div><h3>The file atlas</h3><p>All ${book.files.length} tracked files with descriptions and integrity metadata.</p></div><a class="secondary-button" href="file-atlas.json" download>Download atlas ↓</a></div><p class="modal-note">This page’s narration is also available from the player’s download control. The web reader saves your progress locally; it does not upload your reading history.</p>`)}
function expandImage(src,alt){$('#expanded-image').src=src;$('#expanded-image').alt=alt;$('#expanded-caption').textContent=alt;$('#image-modal').showModal()}

async function init(){
 try{const response=await fetch('book.json');if(!response.ok)throw Error('Book data unavailable');book=await response.json()}catch{$('#spread').innerHTML='<div class="paper-page"><h1>The book could not load.</h1><p>Please reload when your connection is available.</p></div>';return}
 visited=new Set(readStore('swarm-book-visited',[]).filter(i=>i>=0&&i<book.pages.length));marks=new Set(readStore('swarm-bookmarks',[]).filter(i=>i>=0&&i<book.pages.length));settings=readStore('swarm-book-settings',{});$('#auto-turn').checked=settings.autoTurn!==false;$('#speed').textContent=(settings.rate||1)+'×';if(settings.font===1)document.body.classList.add('large-text');if(settings.font===2)document.body.classList.add('larger-text');
 $('#contents').innerHTML=book.chapters.map(c=>`<button class="chapter-link" data-chapter="${c.id}" data-page="${c.start}"><span class="num">${pad(c.id)}</span><span>${escape(c.title)}</span></button>`).join('');$('#chapter-count').textContent=`${book.chapters.length} CHAPTERS`;$('#page-total').textContent=pad(book.pages.length);$('#book-total').textContent=`${book.pages.length} PAGES · ${book.chapters.length} CHAPTERS`;$('#file-count').textContent=book.files.length;document.querySelector('.reading-meta span:last-child').textContent='EDITION / '+book.edition.toUpperCase();
 const saved=readStore('swarm-book-place',{page:0,time:0}),hash=location.hash.match(/^#page=(\d+)$/),start=hash?+hash[1]-1:saved.page||0;navigate(start,{animate:false,restoreTime:start===saved.page?saved.time:0});
 document.addEventListener('click',e=>{
  const src=e.target.closest('[data-source]');if(src){openSource(src.dataset.source);return}
  const page=e.target.closest('[data-page]');if(page){$('#modal').close();navigate(+page.dataset.page);return}
  const action=e.target.closest('[data-action]')?.dataset.action;if(action){if(action==='begin')navigate(1);if(action==='listen')toggleAudio();if(action==='files')openFiles();if(action==='practice')openPractice();return}
  const img=e.target.closest('[data-expand]');if(img)expandImage(img.dataset.expand,img.alt);
 });
 $('#next').onclick=()=>navigate(current+1);$('#prev').onclick=()=>navigate(current-1);$('#play').onclick=toggleAudio;$('#back-audio').onclick=()=>{audio.currentTime=Math.max(0,audio.currentTime-15)};$('#forward-audio').onclick=()=>{audio.currentTime=Math.min(audio.duration||0,audio.currentTime+15)};
 $('#seek').oninput=()=>{if(Number.isFinite(audio.duration))audio.currentTime=+$('#seek').value/1000*audio.duration};$('#speed').onclick=()=>{const rates=[.75,1,1.25,1.5,1.75,2];settings.rate=rates[(rates.indexOf(settings.rate||1)+1)%rates.length];audio.playbackRate=settings.rate;$('#speed').textContent=settings.rate+'×';writeStore('swarm-book-settings',settings)};$('#auto-turn').onchange=()=>{settings.autoTurn=$('#auto-turn').checked;writeStore('swarm-book-settings',settings)};$('#download-audio').onclick=()=>download(book.pages[current].audio);
 $('#open-search').onclick=openSearch;$('#open-files').onclick=openFiles;$('#open-practice').onclick=openPractice;$('#open-downloads').onclick=openDownloads;$('#open-bookmarks').onclick=openBookmarks;
 $('#bookmark-button').onclick=()=>{marks.has(current)?marks.delete(current):marks.add(current);writeStore('swarm-bookmarks',[...marks]);$('#bookmark-button').setAttribute('aria-pressed',String(marks.has(current)));$('#bookmark-button').setAttribute('aria-label',marks.has(current)?'Remove bookmark':'Bookmark this page');toast(marks.has(current)?'Page bookmarked.':'Bookmark removed.')};$('#font-toggle').onclick=()=>{settings.font=((settings.font||0)+1)%3;document.body.classList.toggle('large-text',settings.font===1);document.body.classList.toggle('larger-text',settings.font===2);$('#font-toggle').setAttribute('aria-label',settings.font===2?'Use standard text size':'Increase text size');writeStore('swarm-book-settings',settings);toast(['Standard text size','Larger text','Largest text'][settings.font])};
 $('#toggle-menu').onclick=()=>{const open=$('#sidebar').classList.toggle('open');$('#menu-scrim').hidden=!open;$('#toggle-menu').setAttribute('aria-expanded',String(open))};$('#menu-scrim').onclick=closeMenu;$('#close-modal').onclick=()=>$('#modal').close();$('.image-close').onclick=()=>$('#image-modal').close();
 for(const dialog of [$('#modal'),$('#image-modal')])dialog.addEventListener('click',e=>{const r=dialog.getBoundingClientRect();if(e.target===dialog&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))dialog.close()});
 document.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select')||$('#modal').open||$('#image-modal').open)return;if(e.key==='ArrowRight'){e.preventDefault();navigate(current+1)}else if(e.key==='ArrowLeft'){e.preventDefault();navigate(current-1)}else if(e.key==='/'){e.preventDefault();openSearch()}else if(e.code==='Space'&&!e.target.closest('button,a,summary')){e.preventDefault();toggleAudio()}else if(e.key==='Escape'){closeMenu()}else if(e.key==='Enter'&&e.target.matches('[data-expand]'))expandImage(e.target.dataset.expand,e.target.alt)});
 window.addEventListener('hashchange',()=>{const h=location.hash.match(/^#page=(\d+)$/);if(h)navigate(+h[1]-1)});window.addEventListener('pagehide',savePosition);
 if('mediaSession'in navigator){try{navigator.mediaSession.setActionHandler('play',playAudio);navigator.mediaSession.setActionHandler('pause',()=>audio.pause());navigator.mediaSession.setActionHandler('seekbackward',()=>audio.currentTime=Math.max(0,audio.currentTime-15));navigator.mediaSession.setActionHandler('seekforward',()=>audio.currentTime=Math.min(audio.duration||0,audio.currentTime+15));navigator.mediaSession.setActionHandler('nexttrack',()=>navigate(current+1,{autoplay:true}));navigator.mediaSession.setActionHandler('previoustrack',()=>navigate(current-1,{autoplay:true}))}catch{}}
}
audio.addEventListener('loadedmetadata',()=>{audioReady=true;$('#duration').textContent=time(audio.duration)});audio.addEventListener('play',()=>{updatePlaying();if('mediaSession'in navigator&&typeof MediaMetadata!=='undefined')navigator.mediaSession.metadata=new MediaMetadata({title:book.pages[current].title,artist:'SWARM SAR · English Fieldbook',album:'The Fieldbook'})});audio.addEventListener('pause',()=>{updatePlaying();if(book)savePosition()});audio.addEventListener('timeupdate',()=>{$('#elapsed').textContent=time(audio.currentTime);if(audio.duration)$('#seek').value=audio.currentTime/audio.duration*1000;if(Date.now()-lastSave>3000&&book){savePosition();lastSave=Date.now()}});audio.addEventListener('ended',()=>{if($('#auto-turn').checked&&current<book.pages.length-1)navigate(current+1,{autoplay:true});else toast(current===book.pages.length-1?'You have reached the end of the fieldbook.':'Page narration complete. Turn the page to continue.')});audio.addEventListener('error',()=>{document.body.classList.remove('audio-loading');if(book)toast('Audio could not load. Check the connection and press play again.')});audio.addEventListener('waiting',()=>document.body.classList.add('audio-loading'));audio.addEventListener('playing',()=>document.body.classList.remove('audio-loading'));
init();
